const raw = $json.choices?.[0]?.message?.content ?? '{}';
let parsed;
try { parsed = JSON.parse(raw.replace(/^```json\s*/i, '').replace(/```$/, '').trim()); }
catch { parsed = { research_questions: [raw], search_queries: [raw] }; }
return [{ json: { topic: $('Research Input (edit topic)').first().json.topic, depth: $('Research Input (edit topic)').first().json.depth, research_questions: parsed.research_questions || [], search_queries: parsed.search_queries || [] } }];

const plan = $('Parse Research Plan').first().json;
const results = ($json.results || []).map((r, i) => ({ id: `S${i+1}`, title: r.title || 'Untitled', url: r.url || '', content: r.content || r.raw_content || '', score: r.score ?? null }));
return [{ json: { ...plan, sources: results } }];

const base = $('Attach Fact Check').first().json;
const report = $json.choices?.[0]?.message?.content || 'No report returned.';
return [{ json: { topic: base.topic, research_questions: base.research_questions, sources: base.sources, analysis: base.analysis, fact_check: base.fact_check, report_markdown: report, note: 'Review all citations and source pages before relying on this report.' } }];
